var i=`0245-gigantes-plaki`;var n=`world-0245`;var a=`GR`;var o=`southern-europe`;var r=4;var s=135;var l={en:`Gigantes Plaki`,ua:`Гігантес плакі`};var u={en:`A traditional Greece dish made with butter beans, yellow onion, garlic, carrot. This home-style preparation follows its characteristic cooking method and uses measured ingredients.`,ua:`Традиційна страва кухні країни Греція. Основні інгредієнти: велика біла квасоля, жовта цибуля, часник, морква. Домашній варіант із характерною технологією та поетапно розподіленими продуктами.`};var d=[{en:`Cook the listed ingredients in simmering water for about 90 minutes until tender; drain well if necessary.`,ua:`Варіть зазначені складники у воді приблизно 90 хвилин до м’якості; за потреби добре злийте воду.`,t:[`boiling`],m:90,i:[[`butter-beans`,350,`g`],[`water`,1200,`ml`]]},{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 10 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 10 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:10,i:[[`yellow-onion`,150,`g`],[`garlic`,4,`clove`],[`carrot`,160,`g`],[`extra-virgin-olive-oil`,50,`ml`],[`tomato-passata`,380,`g`]]},{en:`Roast in a preheated 190°C oven for about 35 minutes until nicely browned and fully cooked; turn once if needed.`,ua:`Запікайте в розігрітій до 190°C духовці приблизно 35 хвилин до рум’яності й готовності; за потреби переверніть.`,t:[`roasting`],m:35,i:[[`parsley`,20,`g`],[`dried-oregano`,4,`g`],[`table-salt`,null,`to_taste`]]}];var g={slug:i,id:n,country:`GR`,region:o,servings:4,minutes:135,title:l,text:u,steps:d};export{a as country,g as default,n as id,s as minutes,o as region,r as servings,i as slug,d as steps,u as text,l as title};